INSERT INTO incidents VALUES (1, 'INC-2026-0001', 2, 1, 'Perimeter Breach', '2026-10-28', '02:15', 'Perimeter fence motion sensors triggered near Service Gate 3. Guard on patrol discovered cut chain link fence section. Control room notified and dog unit dispatched; intruder fled.', NULL, 'RESOLVED', '2026-10-28 02:20:00');
INSERT INTO incidents VALUES (2, 'INC-2026-0002', 3, 3, 'Broken Seal / Discrepancy', '2026-10-29', '14:45', 'Inbound container MSKU-482019 arrived with compromised customs bolt seal at Bay 4. Seal number discrepancy logged with shipping agent manifest; container quarantined.', NULL, 'RESOLVED', '2026-10-29 14:50:00');
INSERT INTO incidents VALUES (3, 'INC-2026-0003', 1, 2, 'Unauthorized Access Attempt', '2026-10-30', '21:30', 'Unidentified individual attempted entry to Level 3 Intensive Care corridor without visitor badge. Intercepted at security turnstile and escorted off the premises.', NULL, 'RESOLVED', '2026-10-30 21:35:00');
INSERT INTO incidents VALUES (4, 'INC-2026-0004', 4, 4, 'Fire / Safety Hazard', '2026-10-31', '11:15', 'Electrical arcing and smoke detected in warehouse transformer room. Guard promptly deployed dry powder extinguisher and isolated primary power breaker. Facility engineer notified; repair completed.', NULL, 'OPEN', '2026-10-31 11:20:00');
INSERT INTO incidents VALUES (5, 'INC-2026-0005', 5, 5, 'Suspicious Vehicle', '2026-11-01', '08:20', 'Unattended silver station wagon parked in reserved VIP bay for over 60 minutes with engine idling. License plate logged in Occurrence Book (OB #4492). Driver later identified and moved vehicle.', NULL, 'RESOLVED', '2026-11-01 08:25:00');
INSERT INTO incidents VALUES (6, 'INC-2026-0006', 9, 4, 'Property Damage', '2026-11-01', '13:40', 'Delivery forklift clipped roller shutter door at Loading Dock 2, causing guide track misalignment. Driver details and damage photos recorded; warehouse supervisor notified.', NULL, 'RESOLVED', '2026-11-01 13:45:00');
INSERT INTO incidents VALUES (10, 'INC-2026-0007', 2, 1, 'Other', '2026-11-02', '10:46', 'Fighting and we recovered a stolen items.', NULL, 'OPEN', '2026-11-02 10:46:32');
